// Where each edge's mono label goes in a concept map: the middle of its edge when that spot is clear of nodes and
// earlier labels, else a little to either side, else nowhere, since the line's dash, its ink and the legend still name
// the type. Deterministic: labels are placed in edge order.

type Point = readonly [number, number]

export interface Box {
  x: number
  y: number
  w: number
  h: number
}

const r1 = (n: number) => Math.round(n * 10) / 10
const along = (a: Point, b: Point, u: number) =>
  [a[0] + (b[0] - a[0]) * u, a[1] + (b[1] - a[1]) * u] as const

export function placeLabels(
  edges: readonly { text: string; path: readonly [Point, Point, Point] }[],
  nodes: readonly Box[],
): (Box | null)[] {
  const taken: Box[] = nodes.map((n) => ({ ...n, w: n.w + 6, h: n.h + 4 }))
  return edges.map(({ text, path: [start, mid, end] }) => {
    // JetBrains Mono at 11.5px with 0.06em tracking is about 7.6px a character.
    const w = text.length * 7.6 + 8
    const h = 15
    for (const t of [0.5, 0.4, 0.6, 0.3, 0.7]) {
      const [x, y] =
        t <= 0.5 ? along(start, mid, t * 2) : along(mid, end, (t - 0.5) * 2)
      const clear = taken.every(
        (o) =>
          Math.abs(o.x - x) * 2 >= o.w + w || Math.abs(o.y - y) * 2 >= o.h + h,
      )
      if (clear) {
        const box = { x: r1(x), y: r1(y), w, h }
        taken.push(box)
        return box
      }
    }
    return null
  })
}

// Where a concept map's nodes sit and how its edges are drawn: a pure function of the nodes, edges, types and seed,
// so the same map draws the same way on the server and in the browser. Nodes without a position ring the centre,
// grouped by how they connect to it, at seeded angles; overlapping labels are then pushed apart.
import { sketch, type Pen } from "@/patina/ink/rough"
import { fork, stream } from "@/patina/ink/seed"
import { placeLabels } from "./concept-map-labels"

export interface ConceptNode {
  id: string
  label: string
  /** Position across the map, 0 to 1. Omit x and y to let the seed place the node. */
  x?: number
  /** Position down the map, 0 to 1. */
  y?: number
  shape?: "ellipse" | "box"
}

export interface ConceptEdge {
  from: string
  to: string
  /** The id of one of the map's types. */
  type: string
}

export interface ConceptEdgeType {
  id: string
  /** The type's name in the legend and the list ("Feeds on"). */
  label: string
  /** Words on the edge itself; defaults to the label. */
  short?: string
  /** Draw an arrowhead at the `to` end. */
  directed?: boolean
}

export const MAP_W = 680
export const MAP_H = 460

// Each type gets its own pen: a dash pattern first, an ink from the print set second, so types differ without colour.
const DASHES: (number[] | undefined)[] = [
  undefined,
  [9, 6],
  [1.5, 5],
  [12, 5, 2, 5],
  [18, 7],
]
const INKS = [
  "var(--print-line)",
  "var(--print-accent)",
  "var(--print-detail)",
  "var(--ink-2)",
]
export const edgePen = (index: number) => ({
  dash: DASHES[index % DASHES.length],
  ink: INKS[index % INKS.length]!,
})

const r1 = (n: number) => Math.round(n * 10) / 10
type Point = [number, number]

/** One line, or two balanced lines for a long label. */
function wrap(text: string): string[] {
  if (text.length <= 14 || !text.includes(" ")) return [text]
  const words = text.split(" ")
  let best = [text]
  let diff = Infinity
  for (let i = 1; i < words.length; i++) {
    const a = words.slice(0, i).join(" ")
    const b = words.slice(i).join(" ")
    if (Math.abs(a.length - b.length) < diff)
      [best, diff] = [[a, b], Math.abs(a.length - b.length)]
  }
  return best
}

export interface PlacedNode {
  id: string
  x: number
  y: number
  w: number
  h: number
  lines: string[]
  hub: boolean
  shape: "ellipse" | "box"
  outline: string
  /** A seeded share of --tilt-max, from −2.5 to 2.5. */
  turn: number
}

export interface DrawnEdge {
  svg: string
  /** Where the type's words sit on the edge, or null where there was no clear spot. */
  label: { text: string; x: number; y: number } | null
}

/** Where a ray from a node's centre, heading (dx, dy), leaves its outline, plus a little air. */
function exit(n: PlacedNode, dx: number, dy: number) {
  const a = n.w / 2 + 5
  const b = n.h / 2 + 5
  const k =
    n.shape === "box"
      ? Math.min(a / Math.abs(dx || 1e-6), b / Math.abs(dy || 1e-6))
      : 1 / Math.sqrt((dx / a) * (dx / a) + (dy / b) * (dy / b))
  return [n.x + dx * k, n.y + dy * k] as const
}

export function drawMap(
  nodes: readonly ConceptNode[],
  edges: readonly ConceptEdge[],
  types: readonly ConceptEdgeType[],
  centerId: string | undefined,
  seed: number,
) {
  const hubId = centerId ?? nodes[0]?.id
  const typeIndex = new Map(types.map((t, i) => [t.id, i]))
  const rank = (id: string) => {
    const e =
      edges.find(
        (e) =>
          (e.from === id && e.to === hubId) ||
          (e.to === id && e.from === hubId),
      ) ?? edges.find((e) => e.from === id || e.to === id)
    return e ? (typeIndex.get(e.type) ?? 99) : 99
  }
  const ring = nodes
    .filter((n) => n.id !== hubId && (n.x === undefined || n.y === undefined))
    .sort((a, b) => rank(a.id) - rank(b.id))
  const angle = stream(seed, "layout")
  const start = angle.between(-Math.PI, Math.PI)
  const auto = new Map(
    ring.map((n, i) => {
      const a = start + (i / ring.length) * Math.PI * 2 + angle.signed() * 0.1
      const r = 1 + angle.signed() * 0.06
      return [
        n.id,
        [
          MAP_W / 2 + Math.cos(a) * (MAP_W / 2 - 96) * r,
          MAP_H / 2 + Math.sin(a) * (MAP_H / 2 - 52) * r,
        ],
      ] as const
    }),
  )

  const placed: (PlacedNode & { fixed: boolean })[] = nodes.map((n) => {
    const hub = n.id === hubId
    const lines = wrap(n.label)
    const longest = Math.max(...lines.map((l) => l.length))
    const box = n.shape === "box"
    const w = longest * (hub ? 10 : 8.1) + (hub ? 50 : box ? 26 : 36)
    const h = lines.length * (hub ? 22 : 18) + (hub ? 30 : box ? 16 : 22)
    const given = n.x !== undefined && n.y !== undefined
    const [x, y] = given
      ? [n.x! * MAP_W, n.y! * MAP_H]
      : hub
        ? [MAP_W / 2, MAP_H / 2]
        : auto.get(n.id)!
    return {
      id: n.id,
      x,
      y,
      w,
      h,
      lines,
      hub,
      outline: "",
      turn: stream(fork(seed, n.id), "tilt").signed() * 2.5,
      fixed: given || hub,
      shape: box ? ("box" as const) : ("ellipse" as const),
    }
  })

  // Push overlapping labels apart, then keep every node inside the map. Deterministic: no randomness here.
  // Connected neighbours keep extra room, so the edge between them stays long enough to read.
  const linked = new Set(
    edges.flatMap((e) => [`${e.from}|${e.to}`, `${e.to}|${e.from}`]),
  )
  for (let pass = 0; pass < 60; pass++) {
    for (let i = 0; i < placed.length; i++)
      for (let j = i + 1; j < placed.length; j++) {
        const a = placed[i]!
        const b = placed[j]!
        const air = linked.has(`${a.id}|${b.id}`) ? 2.5 : 1
        const ox = (a.w + b.w) / 2 + 28 * air - Math.abs(a.x - b.x)
        const oy = (a.h + b.h) / 2 + 14 * air - Math.abs(a.y - b.y)
        if (ox <= 0 || oy <= 0 || (a.fixed && b.fixed)) continue
        const share = a.fixed || b.fixed ? 1 : 0.5
        const horizontal = ox / (a.w + b.w) < oy / (a.h + b.h)
        const push = (horizontal ? ox : oy) * share
        const sign = (horizontal ? a.x - b.x : a.y - b.y) >= 0 ? 1 : -1
        const key = horizontal ? "x" : "y"
        if (!a.fixed) a[key] += push * sign
        if (!b.fixed) b[key] -= push * sign
      }
    for (const n of placed) {
      n.x = Math.min(MAP_W - n.w / 2 - 4, Math.max(n.w / 2 + 4, n.x))
      n.y = Math.min(MAP_H - n.h / 2 - 4, Math.max(n.h / 2 + 4, n.y))
    }
  }

  const ground = "var(--concept-map-ground)"
  for (const n of placed) {
    n.x = r1(n.x)
    n.y = r1(n.y)
    const s = fork(seed, `node:${n.id}`)
    const pen: Pen = {
      seed: s,
      stroke: "var(--line)",
      strokeWidth: 1.3,
      roughness: 1.1,
      fill: ground,
      fillStyle: "solid",
    }
    n.outline = n.hub
      ? sketch.ellipse(n.x, n.y, n.w - 8, n.h - 6, {
          seed: s + 3,
          stroke: "none",
          fill: "color-mix(in srgb, var(--k) var(--wash-alpha), var(--concept-map-ground))",
          fillStyle: "solid",
        }) +
        sketch.ellipse(n.x, n.y, n.w, n.h, {
          seed: s,
          stroke: "var(--k)",
          strokeWidth: 2.2,
          roughness: 1.3,
        }) +
        sketch.ellipse(n.x + 2, n.y - 1, n.w - 6, n.h - 4, {
          seed: s + 2,
          stroke: "var(--k)",
          strokeWidth: 1,
          roughness: 1.6,
        })
      : n.shape === "box"
        ? sketch.rect(n.x - n.w / 2, n.y - n.h / 2, n.w, n.h, {
            ...pen,
            roughness: 0.9,
          })
        : sketch.ellipse(n.x, n.y, n.w, n.h, pen)
  }

  const byId = new Map(placed.map((n) => [n.id, n]))
  const drawn: { svg: string; text: string; path: [Point, Point, Point] }[] = []
  edges.forEach((e, i) => {
    const a = byId.get(e.from)
    const b = byId.get(e.to)
    const index = typeIndex.get(e.type)
    if (!a || !b || index === undefined) return
    const type = types[index]!
    const len = Math.hypot(b.x - a.x, b.y - a.y) || 1
    const dx = (b.x - a.x) / len
    const dy = (b.y - a.y) / len
    const [sx, sy] = exit(a, dx, dy)
    const [ex, ey] = exit(b, -dx, -dy)
    const s = fork(seed, `edge:${i}:${e.from}:${e.to}`)
    const bend = stream(s, "bend").signed() * 0.1 * len
    const mx = r1((sx + ex) / 2 - dy * bend)
    const my = r1((sy + ey) / 2 + dx * bend)
    const { dash, ink } = edgePen(index)
    const pen: Pen = { seed: s, stroke: ink, strokeWidth: 1.6, roughness: 1 }
    let svg = sketch.curve(
      [
        [sx, sy],
        [mx, my],
        [ex, ey],
      ],
      { ...pen, ...(dash ? { strokeLineDash: dash } : {}) },
    )
    if (type.directed) {
      const head = Math.atan2(ey - my, ex - mx)
      for (const side of [0.82, -0.82])
        svg += sketch.line(
          ex,
          ey,
          ex + Math.cos(head + Math.PI * side) * 9,
          ey + Math.sin(head + Math.PI * side) * 9,
          { ...pen, seed: s + (side > 0 ? 1 : 2) },
        )
    }
    drawn.push({
      svg,
      text: (type.short ?? type.label).toUpperCase(),
      path: [
        [sx, sy],
        [mx, my],
        [ex, ey],
      ],
    })
  })

  const spots = placeLabels(drawn, placed)
  const lines: DrawnEdge[] = drawn.map((e, i) => {
    const spot = spots[i]
    return { svg: e.svg, label: spot ? { text: e.text, ...spot } : null }
  })
  return { nodes: placed, edges: lines }
}

"use client"

import * as React from "react"
import { sketch } from "@/patina/ink/rough"
import { cn } from "@/patina/lib/utils"
import { useSeed } from "@/patina/print/seed-scope"
import {
  drawMap,
  edgePen,
  MAP_H,
  MAP_W,
  type ConceptEdge,
  type ConceptEdgeType,
  type ConceptNode,
} from "./concept-map-layout"

// A hand-drawn graph of typed connections (Mental Models' ConnectionMap). The centre node sits in a double ring over a
// wash of the drum; the others are serif labels in drawn ellipses or boxes, each leaning by a seeded share of
// --tilt-max. Edges are rough lines whose type shows in a dash pattern, an ink and a mono label, with a legend below.
// A graph does not read at phone width, so a narrow container gets the grouped list instead; that list is also what
// assistive technology reads at every width, and the drawing is hidden from it.

export type { ConceptEdge, ConceptEdgeType, ConceptNode }

export interface ConceptMapProps extends Omit<
  React.ComponentProps<"figure">,
  "children"
> {
  nodes: readonly ConceptNode[]
  edges: readonly ConceptEdge[]
  /** The kinds of connection, in legend order. */
  types: readonly ConceptEdgeType[]
  /** The id of the node the map is about. Defaults to the first node. */
  center?: string
  /** The map's accessible name, e.g. "How the grey heron connects". */
  label: string
  seed?: string | number
}

const sample = (index: number, directed?: boolean) => {
  const { dash, ink } = edgePen(index)
  const pen = { seed: 7 + index, stroke: ink, strokeWidth: 1.6, roughness: 0.7 }
  return (
    sketch.line(2, 5, 34, 5, {
      ...pen,
      ...(dash ? { strokeLineDash: dash } : {}),
    }) +
    (directed
      ? sketch.line(34, 5, 28, 1.5, pen) + sketch.line(34, 5, 28, 8.5, pen)
      : "")
  )
}

function ConceptMap({
  nodes,
  edges,
  types,
  center,
  label,
  seed,
  className,
  ...props
}: ConceptMapProps) {
  const s = useSeed("concept-map", seed ?? label)
  const map = React.useMemo(
    () => drawMap(nodes, edges, types, center, s),
    [nodes, edges, types, center, s],
  )
  const samples = React.useMemo(
    () => types.map((t, i) => sample(i, t.directed)),
    [types],
  )
  const byId = new Map(nodes.map((n) => [n.id, n]))
  const hub = byId.get(center ?? "") ?? nodes[0]
  const groups = types
    .map((type) => ({ type, edges: edges.filter((e) => e.type === type.id) }))
    .filter((g) => g.edges.length > 0)

  return (
    <figure
      data-slot="concept-map"
      aria-label={label}
      className={cn(
        "@container/concept-map m-0 w-full min-w-0 [--concept-map-ground:var(--paper)]",
        className,
      )}
      {...props}
    >
      <div
        aria-hidden="true"
        data-slot="concept-map-graph"
        className="hidden max-w-[46rem] flex-col gap-tight @min-[40rem]/concept-map:flex"
      >
        <svg
          viewBox={`0 0 ${MAP_W} ${MAP_H}`}
          className="block h-auto w-full overflow-visible"
        >
          {map.edges.map((e, i) => (
            <g key={i} dangerouslySetInnerHTML={{ __html: e.svg }} />
          ))}
          {map.edges.map((e, i) =>
            e.label ? (
              <text
                key={i}
                x={e.label.x}
                y={e.label.y + 4}
                textAnchor="middle"
                className="font-label text-[11.5px] font-semibold tracking-[0.06em]"
                style={{
                  fill: "var(--ink-2)",
                  stroke: "var(--concept-map-ground)",
                  strokeWidth: 5,
                  strokeLinejoin: "round",
                  paintOrder: "stroke",
                }}
              >
                {e.label.text}
              </text>
            ) : null,
          )}
          {map.nodes.map((n) => (
            <g
              key={n.id}
              data-hub={n.hub || undefined}
              style={{
                rotate: `calc(var(--tilt-max) * ${n.turn.toFixed(2)})`,
                transformBox: "fill-box",
                transformOrigin: "center",
              }}
            >
              <g dangerouslySetInnerHTML={{ __html: n.outline }} />
              {n.lines.map((line, i) => (
                <text
                  key={i}
                  x={n.x}
                  y={
                    n.y +
                    (n.hub ? 6.5 : 5.5) -
                    ((n.lines.length - 1) * (n.hub ? 22 : 18)) / 2 +
                    i * (n.hub ? 22 : 18)
                  }
                  textAnchor="middle"
                  className={cn(
                    "font-read",
                    n.hub
                      ? "text-[19px] font-bold"
                      : "text-[15px] font-semibold",
                  )}
                  style={{ fill: "var(--ink)" }}
                >
                  {line}
                </text>
              ))}
            </g>
          ))}
        </svg>
        <ul
          data-slot="concept-map-legend"
          className="m-0 flex list-none flex-wrap gap-x-snug gap-y-hair p-0"
        >
          {types.map((type, i) => (
            <li
              key={type.id}
              className="flex items-center gap-hair font-label text-label leading-[1.45] font-medium tracking-[0.06em] text-ink-2 uppercase"
            >
              <svg
                viewBox="0 0 36 10"
                className="h-2.5 w-9 shrink-0 overflow-visible"
                dangerouslySetInnerHTML={{ __html: samples[i]! }}
              />
              {type.label}
            </li>
          ))}
        </ul>
      </div>
      <div
        data-slot="concept-map-list"
        className="sr-only @max-[40rem]/concept-map:not-sr-only @max-[40rem]/concept-map:flex @max-[40rem]/concept-map:flex-col"
      >
        {hub ? (
          <p className="m-0 border-b-[1.5px] border-line pb-hair font-read text-body leading-subhead font-semibold text-ink">
            {hub.label}
          </p>
        ) : null}
        <dl className="m-0">
          {groups.map(({ type, edges: group }) => (
            <div
              key={type.id}
              className="border-b border-dashed border-rule py-tight last:border-b-0"
            >
              <dt className="label-mono text-k-ink">{type.label}</dt>
              <dd className="m-0 mt-1">
                <ul className="m-0 flex list-none flex-wrap p-0 text-ui leading-ui text-ink">
                  {group.map((e, i) => {
                    const from = byId.get(e.from)?.label ?? e.from
                    const to = byId.get(e.to)?.label ?? e.to
                    const other =
                      e.from === hub?.id ? to : e.to === hub?.id ? from : null
                    return (
                      <li
                        key={i}
                        className="after:mx-1.5 after:text-ink-faint after:content-['·'_/_''] last:after:content-none"
                      >
                        {other ?? (
                          <>
                            {from} <span aria-hidden="true">→</span>
                            <span className="sr-only">
                              {(type.short ?? type.label).toLowerCase()}
                            </span>{" "}
                            {to}
                          </>
                        )}
                      </li>
                    )
                  })}
                </ul>
              </dd>
            </div>
          ))}
        </dl>
      </div>
    </figure>
  )
}

export { ConceptMap }
